import { resolveHostedTaskInput } from "./task-input.js";
import { AGENT_ERROR } from "../../errors/index.js";
import { createChatUiMessageStreamFromDataStream } from "../streaming/chat-ui-message-stream.js";
import { createToolExecutionDataEventBridgeStream } from "../streaming/tool-execution-data-event-bridge.js";
import { runWithEffectiveSourceIntegrationPolicy } from "../../integrations/source-policy-context.js";
function previewToolInput(inputText) {
    return inputText.length > 500 ? `${inputText.slice(0, 500)}...` : inputText;
}
/** Create hosted chat runtime agent adapter. */
export function createHostedChatRuntimeAgentAdapter(input) {
    const taskInput = resolveHostedTaskInput(input.taskInput, input);
    input = { ...input, taskInput };
    const runStream = input.runStream ?? ((operation) => operation());
    return {
        stream: async (streamInput) => {
            const stream = await createHostedChatRuntimeDataStream(input, streamInput, runStream);
            return {
                steps: Promise.resolve([]),
                toUIMessageStream(options = {}) {
                    return createChatUiMessageStreamFromDataStream({ stream }, {
                        generateMessageId: options.generateMessageId,
                        sendReasoning: options.sendReasoning,
                        onError: options.onError,
                        messageMetadata: options.messageMetadata,
                        onFinish: options.onFinish,
                        privateRuntimeObservations: streamInput.runtimeObservations === true,
                        onOrphanedToolInput: ({ toolCallId, inputText }) => {
                            input.warnOrphanedToolInput?.("Dropping orphan AG-UI runtime tool-input-delta stream without a matching lifecycle", {
                                toolCallId,
                                inputPreview: previewToolInput(inputText),
                            });
                        },
                    });
                },
            };
        },
    };
}
/** @internal Start the runtime data stream without installing broker UI callbacks. */
export async function createHostedChatRuntimeDataStream(input, streamInput, runStream = input.runStream ?? ((operation) => operation())) {
    let publishDataEvent = (_event) => { };
    const streamResponse = await runStream(() => runWithEffectiveSourceIntegrationPolicy(input.sourceIntegrationPolicy, async () => {
        const projectContext = input.resolveProjectContext?.() ?? {
            projectId: input.projectId,
            projectSlug: input.projectSlug,
        };
        const taskInput = resolveHostedTaskInput(input.taskInput, {
            projectId: projectContext?.projectId,
            rootRunId: input.rootRunId,
            runId: input.runId,
        });
        const response = await input.runtimeAgent.stream({
            messages: streamInput.messages,
            ...(input.maxOutputTokens !== undefined
                ? { maxOutputTokens: input.maxOutputTokens }
                : {}),
            context: {
                ...(taskInput ? { taskInput } : {}),
                ...(input.rootRunId ? { rootRunId: input.rootRunId } : {}),
                ...(input.runId ? { runId: input.runId } : {}),
                ...(input.agentId ? { agentId: input.agentId } : {}),
                ...(input.conversationId ? { conversationId: input.conversationId } : {}),
                ...(projectContext?.projectId ? { projectId: projectContext.projectId } : {}),
                ...(projectContext?.projectSlug ? { projectSlug: projectContext.projectSlug } : {}),
                ...(streamInput.runtimeObservations ? { runtimeObservations: true } : {}),
                abortSignal: streamInput.abortSignal,
                publishDataEvent: (event) => publishDataEvent(event),
            },
        });
        return response.toDataStreamResponse();
    }));
    if (!streamResponse.body) {
        throw AGENT_ERROR.create({ detail: "Agent runtime returned an empty stream body" });
    }
    return createToolExecutionDataEventBridgeStream({
        baseStream: streamResponse.body,
        installPublisher: (nextPublishDataEvent) => {
            publishDataEvent = nextPublishDataEvent;
        },
    });
}
